import { Component, inject, signal } from '@angular/core';
import { Session } from '../../core/session';
import { SheetSettings } from '../../core/settings';

// The policy viewer: one line per policy version, the first made first, as
// <version> <from or start> <key>=<value> <count of claims whose policy version it is>.
@Component({
  selector: 'app-policy-viewer',
  template: `
    <section aria-labelledby="policy-heading">
      <h3 id="policy-heading">Policy versions</h3>
      <button type="button" data-testid="policy-show" (click)="show()">Show policy versions</button>
      @if (error()) {
        <p role="alert" data-testid="policy-error">{{ error() }}</p>
      }
      @if (lines(); as shown) {
        <ul>
          @for (line of shown; track $index) {
            <li data-testid="policy-line">{{ line }}</li>
          }
        </ul>
      }
    </section>
  `,
})
export class PolicyViewer {
  private readonly api = inject(SheetSettings);
  private readonly session = inject(Session);

  protected readonly lines = signal<string[] | null>(null);
  protected readonly error = signal('');

  protected async show(): Promise<void> {
    const sheet = this.session.sheetId();
    if (!sheet) return;
    this.error.set('');
    this.lines.set(null);
    try {
      const versions = await this.api.policyLines(sheet);
      this.lines.set(versions.map((v) => `${v.number} ${v.from ?? 'start'} ${v.key}=${v.value ?? ''} ${v.claims}`));
    } catch {
      this.error.set('The policy versions could not be shown.');
    }
  }
}
import { Component, inject, signal } from '@angular/core';
import { downloadCsv } from '../../core/csv';
import { Session } from '../../core/session';
import { TreeSearch } from '../../core/tree-search';

// The tree export: downloads the people of the sheet's whole tree as a CSV file, a header line
// sheet,name,grade,due-total then one line per person, this sheet first, then the others by id.
@Component({
  selector: 'app-tree-export-button',
  template: `
    <button type="button" data-testid="export-tree" (click)="exportCsv()">Export tree people (CSV)</button>
    @if (error()) {
      <p role="alert" data-testid="export-tree-error">{{ error() }}</p>
    }
  `,
})
export class TreeExportButton {
  private readonly api = inject(TreeSearch);
  private readonly session = inject(Session);

  protected readonly error = signal('');

  protected async exportCsv(): Promise<void> {
    const sheet = this.session.sheetId();
    if (!sheet) return;
    this.error.set('');
    try {
      const people = await this.api.people(sheet);
      const lines = [['sheet', 'name', 'grade', 'due-total'], ...people.map((p) => [p.sheet, p.name, p.grade, p.dueTotal])];
      downloadCsv(lines, 'tree.csv');
    } catch {
      this.error.set('The tree could not be exported.');
    }
  }
}

