                return sheets.floor(sheetId, day);
            }

            @Override
            public BigDecimal latePct(LocalDate day) {
                return sheets.latePct(sheetId, day);
            }

            @Override
            public BigDecimal cap(LocalDate day) {
                return sheets.cap(sheetId, day);
            }

